-- Batch HOME — the homepage-as-magazine content infrastructure.
-- EditorialCard powers every non-project block (hero banners, announcements,
-- success stories, interviews, resources, tips, trust guides). kind is TEXT
-- (validated in the DTO) to spare enum-migration churn.
CREATE TABLE "EditorialCard" (
    "id"          UUID NOT NULL DEFAULT gen_random_uuid(),
    "kind"        TEXT NOT NULL,
    "slug"        TEXT,
    "titleAr"     TEXT NOT NULL,
    "bodyAr"      TEXT NOT NULL,
    "bodyLongAr"  TEXT,
    "imageUrl"    TEXT,
    "linkUrl"     TEXT,
    "linkLabelAr" TEXT,
    "isActive"    BOOLEAN NOT NULL DEFAULT true,
    "sortOrder"   INTEGER NOT NULL DEFAULT 0,
    "publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "EditorialCard_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "EditorialCard_slug_key" ON "EditorialCard"("slug");
CREATE INDEX "EditorialCard_kind_isActive_sortOrder_idx" ON "EditorialCard"("kind", "isActive", "sortOrder");

-- HomepageSection — admin toggles/reorders the page without deploys.
CREATE TABLE "HomepageSection" (
    "key"       TEXT NOT NULL,
    "isActive"  BOOLEAN NOT NULL DEFAULT true,
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT "HomepageSection_pkey" PRIMARY KEY ("key")
);

INSERT INTO "HomepageSection" ("key", "isActive", "sortOrder") VALUES
  ('hero_banners', true, 1), ('featured_recommended', true, 2),
  ('announcements', true, 3), ('collection_showcase', true, 4),
  ('brand_program', true, 5), ('home_stretch', true, 6),
  ('success_stories', true, 7), ('creator_interviews', true, 8),
  ('fresh_favorites', true, 9), ('creators_corner', true, 10),
  ('funding_tips', true, 11), ('trust_duo', true, 12);

-- Seed: real Wathba editorial content (no lorem). Admin CRUD owns it from here.
INSERT INTO "EditorialCard" ("kind", "slug", "titleAr", "bodyAr", "bodyLongAr", "linkUrl", "linkLabelAr", "sortOrder") VALUES
-- S1 hero banners
('HERO_BANNER', NULL, 'قوة الإيمان بالفكرة', 'كل مشروع عظيم بدأ بشخصٍ آمن بفكرته قبل أن يراها أحد. وثبة تحوّل هذا الإيمان إلى دعمٍ حقيقي من مجتمعك.', NULL, '/projects/start', 'ابدأ مشروعك', 1),
('HERO_BANNER', NULL, 'مبدعات سعوديات', 'حملة تسلّط الضوء على مشاريع تقودها مبدعات من مختلف مناطق المملكة — اكتشفي وادعمي.', NULL, '/projects/discover-all?collection=saudi-women-creators', 'اكتشف الحملة', 2),
('HERO_BANNER', NULL, 'اصنع في السعودية', 'من الفكرة إلى المصنع: مشاريع صناعية ناشئة تبني منتجاتها محلياً بدعم جماعي شفاف.', NULL, '/projects/discover-all?collection=made-in-saudi', 'تصفّح المشاريع', 3),
-- S3/S5 announcements + program
('ANNOUNCEMENT', NULL, 'حملة اصنع في السعودية مفتوحة الآن', 'قدّم مشروعك الصناعي قبل نهاية الشهر ليُعرض ضمن الحملة على الصفحة الرئيسية وقنواتنا.', NULL, '/projects/start', 'قدّم مشروعك', 1),
('ANNOUNCEMENT', NULL, 'ورشة: كيف تطلق مشروعك على وثبة', 'جلسة أسبوعية مباشرة مع فريق المنصة: بناء الصفحة، تسعير المكافآت، وخطة الحملة — سجّل مجاناً.', NULL, '/projects/handbook', 'دليل الناشر', 2),
('ANNOUNCEMENT', NULL, 'صندوق دعم المشاريع الناشئة — قريباً', 'برنامج تمويل مشترك يضاعف أثر دعم المجتمع للمشاريع الواعدة. التفاصيل تُعلن قريباً.', NULL, '/projects/about', 'عن وثبة', 3),
-- S7 success stories (article pages)
('SUCCESS_STORY', 'sirb-story', 'سِرب: من ورشة صغيرة إلى ٢٬٨٤٧ داعماً', 'كيف حوّل سبعة مهندسين فكرة درون تصوير ذكي إلى أنجح حملة تقنية على وثبة.', 'بدأت قصة سِرب في ورشة صغيرة شرق الرياض، حيث اجتمع سبعة مهندسين حول سؤال واحد: لماذا لا يُصنع درون التصوير الاحترافي هنا؟' || E'\n\n' || 'اختار الفريق وثبة لأن نموذج الضمان — لا خصم قبل بلوغ ٨٠٪ من الهدف — منحهم مصداقية أمام داعمين لا يعرفونهم. بنوا صفحة حملة شفافة: مواصفات كاملة، مخاطر معلنة، وجدول مراحل بتواريخ حقيقية.' || E'\n\n' || 'النتيجة: ٢٬٨٤٧ داعماً و١٧١٪ من الهدف، ثم تسليم أول دفعة خلال الموعد. الدرس الأهم في كلمات مؤسسهم: «الشفافية ليست قسماً في الصفحة — هي الصفحة كلها».', NULL, NULL, 1),
('SUCCESS_STORY', 'najd-crafts-story', 'حِرف نجد: السدو يصل إلى ١٢ دولة', 'تعاونية حرفيات حوّلت نقوش السدو التراثية إلى علامة معاصرة تُشحن حول العالم.', 'حين أطلقت تعاونية حرفيات نجد حملتها، كان الهدف متواضعاً: تمويل أنوالٍ جديدة. لكن القصة التي روتها الصفحة — نقوشٌ توارثتها ثلاثة أجيال تبحث عن جيلٍ رابع — لمست وتراً أعمق.' || E'\n\n' || 'استخدمت التعاونية تحديثات الحملة أسبوعياً: صور من الورشة، وأصوات الحرفيات أنفسهن. تجاوزت الحملة هدفها، والأهم أن ٤٠٪ من الداعمين طلبوا الطلبية الثانية بعد التسليم.' || E'\n\n' || 'اليوم تشحن التعاونية إلى ١٢ دولة، وتدرّب ١٥ حرفية جديدة سنوياً من عائدات مستدامة بدأت بحملة واحدة.', NULL, NULL, 2),
('SUCCESS_STORY', 'qamar-games-story', 'لعبة قمر: أول لعبة طاولة سعودية تتجاوز هدفها في ٤٨ ساعة', 'مصممان شابان أثبتا أن ألعاب الطاولة العربية سوقٌ حقيقي لا هواية هامشية.', 'رفض الناشرون التقليديون لعبة قمر ثلاث مرات بحجة أن «ألعاب الطاولة العربية لا تبيع». قرر مصمماها الاحتكام إلى الجمهور مباشرة عبر وثبة.' || E'\n\n' || 'صمّما صفحة الحملة كأنها جولة داخل اللعبة: فيديو تجريبي، وقواعد كاملة قابلة للتحميل، ونسخة رقمية مجانية لكل داعم مبكر. بلغت الحملة هدفها في ٤٨ ساعة وأغلقت على ٢٤٠٪.' || E'\n\n' || 'الدرس: الشفافية الكاملة عن المنتج — حتى قواعده — لا تقتل المبيعات؛ بل تصنع الثقة التي تسبقها.', NULL, NULL, 3),
('SUCCESS_STORY', 'atr-alsharq-story', 'عطر الشرق: علامة عطور من حي الطائف القديم', 'مشروع عائلي حوّل تقطير الورد الطائفي إلى علامة عطور حديثة بتمويل مجتمعي.', 'ورث سليمان مصنع تقطير ورد صغيراً في الطائف، وورث معه سؤالاً: كيف ينافس منتجٌ حرفي علاماتٍ عالمية؟ كانت إجابته حملة على وثبة تروي رحلة الوردة من الحقل إلى القارورة.' || E'\n\n' || 'قدّمت الحملة مكافآت ذكية: باقة «سمِّ عطرك» دعت الداعمين للمشاركة في تسمية الإصدار الأول، فتحوّل الداعمون إلى سفراء للعلامة قبل صدورها.' || E'\n\n' || 'أغلقت الحملة على ١٥٦٪ من الهدف، وأصبح «عطر الداعمين الأول» أكثر منتجات العلامة مبيعاً حتى اليوم.', NULL, NULL, 4),
-- S8 creator interviews
('CREATOR_INTERVIEW', 'interview-sirb', 'حوار: مؤسس سِرب عن هندسة الثقة', '«الداعم لا يشتري منتجاً — يشتري صدقك في التنفيذ». حوار حول بناء حملة تقنية موثوقة.', 'س: ما أصعب قرار في حملتكم؟' || E'\n\n' || 'ج: إعلان المخاطر بصراحة. كتبنا قسم المخاطر قبل أي قسم آخر: مشاكل سلاسل التوريد، احتمالات تأخر الشهادات اللاسلكية، وحتى سيناريو فشل النموذج النهائي. توقعنا أن يُخيف ذلك الداعمين — حدث العكس تماماً.' || E'\n\n' || 'س: نصيحتك لمبدع تقني يبدأ اليوم؟' || E'\n\n' || 'ج: اجعل تحديثاتك مملة تقنياً وممتعة إنسانياً. الداعم يريد أن يرى الشاشة التي تعمل والوجه المرهق خلفها — كلاهما.', NULL, NULL, 1),
('CREATOR_INTERVIEW', 'interview-najd', 'حوار: حرفيات نجد عن التسعير العادل', 'كيف تُسعّر منتجاً حرفياً دون أن تبخس الحرفة أو ترهق الداعم؟', 'س: كيف حسبتنّ أسعار المكافآت؟' || E'\n\n' || 'ج: بدأنا من أجر الحرفية بالساعة — لا من سعر السوق. سعر السوق للسدو مضغوط بمنتجات مقلّدة مستوردة؛ لو جارَيناه لدفعنا لحرفياتنا أقل من حقهن. كتبنا هذه الحسبة في صفحة الحملة نفسها.' || E'\n\n' || 'س: وماذا كانت النتيجة؟' || E'\n\n' || 'ج: لم يعترض داعم واحد على السعر. حين ترى تفصيل التكلفة أمامك، يتحول السعر من رقم إلى موقف.', NULL, NULL, 2),
('CREATOR_INTERVIEW', 'interview-qamar', 'حوار: مصمما قمر عن الرفض ثم النجاح', 'ثلاث رسائل رفض من الناشرين، ثم ٢٤٠٪ من الهدف — ماذا تغيّر؟', 'س: ماذا قالت رسائل الرفض؟' || E'\n\n' || 'ج: جميعها بصيغة واحدة تقريباً: السوق صغير. لكن أحداً لم يُرِنا بيانات. قررنا أن نصنع البيانات بأنفسنا: الحملة كانت دراسة السوق التي لم يجرِها أحد.' || E'\n\n' || 'س: ما الذي صنع الفارق في الحملة؟' || E'\n\n' || 'ج: النسخة التجريبية المجانية. من جرّب اللعبة ورقياً دعم النسخة الفاخرة. القاعدة عندنا صارت: أعطِ القيمة أولاً، واطلب الدعم ثانياً.', NULL, NULL, 3),
('CREATOR_INTERVIEW', 'interview-atr', 'حوار: سليمان عن المشاريع العائلية', 'الجيل الثاني في مصنع التقطير يشرح كيف يُحدّث إرثاً دون أن يفقده.', 'س: ما الذي أضافته وثبة لمشروع عمره أربعون عاماً؟' || E'\n\n' || 'ج: جمهوراً يرى القيمة قبل المنتج. زبون المتجر يشتري قارورة؛ داعم الحملة يشتري القصة والمصنع والعائلة. هؤلاء لا يغادرون بعد التسليم.' || E'\n\n' || 'س: نصيحة للمشاريع العائلية المترددة؟' || E'\n\n' || 'ج: إرثكم ليس سراً تحمونه — إنه أفضل صفحة حملة لم تكتبوها بعد.', NULL, NULL, 4),
-- S10 creators corner resources
('RESOURCE', NULL, 'دليل الناشر الكامل', 'كل ما تحتاجه قبل الإطلاق: القواعد، معايير المراجعة، وبناء صفحة تستحق الدعم.', NULL, '/projects/handbook', 'اقرأ الدليل', 1),
('RESOURCE', 'reward-pricing-guide', 'تسعير المكافآت دون خسارة', 'المعادلة العملية: التكلفة + الشحن + هامش الأمان، وأخطاء التسعير الخمسة الشائعة.', 'التسعير الخاطئ هو القاتل الصامت للحملات الناجحة: حملة تبلغ هدفها ثم تكتشف أن كل مكافأة تُسلَّم بخسارة.' || E'\n\n' || 'المعادلة الأساسية: تكلفة الإنتاج الفعلية + تكلفة الشحن والتغليف + ١٥٪ هامش أمان للمفاجآت + رسوم المنصة والمعالجة. إن تجاوز الناتج سعر السوق فراجع المنتج، لا الهامش.' || E'\n\n' || 'الأخطاء الخمسة الشائعة: تسعير الشحن الدولي كالمحلي، تجاهل رسوم المعالجة، مكافأة مبكرة رخيصة بكمية مفتوحة، حساب التكلفة على أسعار اليوم لمواد تُشترى بعد ستة أشهر، ونسيان تكلفة وقتك أنت.', NULL, NULL, 2),
('RESOURCE', 'fulfillment-guide', 'التنفيذ والشحن من الألف إلى الياء', 'خطة التسليم التي تكتبها قبل الإطلاق — لا بعده: موردون بدلاء، جدول واقعي، وتواصل استباقي.', 'أكثر أسباب تعثّر الحملات ليست في التمويل — بل فيما بعده. خطة التنفيذ تُكتب قبل الإطلاق وتُختبر ضد ثلاثة أسئلة.' || E'\n\n' || 'أولاً: هل لكل مورد رئيسي بديل جاهز؟ ثانياً: هل جدولك يتحمل تأخراً شهرين دون كارثة؟ ثالثاً: هل حسبت الشحن بالوزن الحجمي لا الفعلي؟' || E'\n\n' || 'وقاعدة التواصل الذهبية: الخبر السيئ المبكر أفضل من الصمت المطمئن. داعموك شركاء رحلة — أخبرهم بالمطبات قبل أن يشعروا بها.', NULL, NULL, 3),
('RESOURCE', NULL, 'مستجدات المنصة', 'آخر ما أطلقناه في وثبة: التقسيط عبر تابي وتمارا، نافذة الإلغاء، وحماية الحملات.', NULL, '/projects/about', 'اطّلع على الجديد', 4),
-- S11 funding tips
('TIP', NULL, 'دليل الداعم الذكي', 'اقرأ قسم المخاطر أولاً، وتحقق من توثيق نفاذ، وراقب جدية التحديثات قبل أن تدعم.', NULL, '/projects/how', 'كيف تعمل وثبة', 1),
('TIP', 'staff-pick-guide', 'كيف تحصل على «مختارات وثبة»', 'المعايير الحقيقية التي يبحث عنها فريق التحرير — وما الذي لا يهم إطلاقاً.', 'شارة «مختارات وثبة» لا تُشترى ولا تُطلب — تُكتسب. فريق التحرير يراجع الحملات الجديدة أسبوعياً ضد أربعة معايير.' || E'\n\n' || 'الفكرة الأصيلة: هل تحل مشكلة حقيقية أو تقدّم جمالاً أصيلاً؟ الصفحة المكتملة: فيديو حقيقي، مخاطر مكتوبة بصدق، مراحل بتواريخ. الجدية التنفيذية: نموذج أولي ملموس يتفوق على عرضٍ تقديمي أنيق. والمجتمع: مبدع يرد على التعليقات خلال ساعات لا أيام.' || E'\n\n' || 'وما الذي لا يهم؟ حجم الهدف، وشهرة المبدع، وعدد المتابعين. أصغر حملة بصفحة صادقة تسبق أكبر اسم بصفحة مستعجلة.', NULL, NULL, 2),
('TIP', NULL, 'قصة رقمية: ماذا تخبرنا بيانات المنصة؟', 'الحملات التي تنشر تحديثاً أسبوعياً تبلغ أهدافها بمعدل الضعف. الأرقام لا تجامل.', NULL, '/projects/discover-all', 'استكشف بنفسك', 3),
('TIP', NULL, 'لماذا ٨٠٪ وليس ١٠٠٪؟', 'عتبة النجاح المرنة تحمي المشاريع الجادة من فشلٍ شكلي — وتحمي الداعم بضمان التنفيذ نفسه.', NULL, '/projects/how', 'اقرأ التفاصيل', 4),
-- S12 trust duo (the scam-protection article is REQUIRED real content)
('TRUST_GUIDE', 'protect-your-campaign', 'كيف تحمي حملتك من الاحتيال', 'انتحال الشخصية، التلاعب بالتعهدات، وعروض التسويق المشبوهة — دليل عملي للمبدع والداعم.', 'الاحتيال في التمويل الجماعي لا يستهدف المنصة — يستهدفك أنت. هذا الدليل يغطي الأنماط الثلاثة الأكثر شيوعاً وكيف تتصرف حيالها.' || E'\n\n' || '١) انتحال الشخصية: حسابات تقلّد اسم حملتك أو صورك على وسائل التواصل وتطلب «دفعات مباشرة» خارج المنصة. القاعدة: وثبة لا تطلب دفعاً خارج صفحات المنصة أبداً، وكل مبدع موثّق عبر نفاذ. أبلغ عن الحساب المنتحل في منصته، وأخطر داعميك عبر تحديث رسمي في الحملة.' || E'\n\n' || '٢) التلاعب بالتعهدات: تعهدات كبيرة مفاجئة تهدف لدفع الحملة فوق العتبة ثم تُلغى، أو بطاقات مسروقة تُكتشف لاحقاً. حماية المنصة: قفل التعهدات قبل ٤٨ ساعة من الإغلاق، وتقييم النجاح عند الموعد النهائي فقط، والتحقق من كل عملية. إن لاحظت نمطاً غريباً في تعهداتك أبلغ الدعم فوراً — لا تنتظر الإغلاق.' || E'\n\n' || '٣) عروض التسويق المشبوهة: رسائل تعدك بـ«آلاف الداعمين مقابل رسوم» أو «قوائم داعمين مضمونة». جميعها إما احتيال مباشر أو مخالفة تُعرّض حملتك للإيقاف. التسويق المشروع يبني جمهوراً — لا يبيعه.' || E'\n\n' || 'قناة الإبلاغ: support@wathba.sa أو نموذج «تواصل معنا» — يصل البلاغ لفريق الثقة والأمان مباشرة، ويُراجع خلال يوم عمل.', NULL, NULL, 1),
('TRUST_GUIDE', 'data-story-transparency', 'قصة بيانات: أثر الشفافية بالأرقام', 'ماذا يحدث للحملات التي تنشر مخاطرها بصراحة؟ نظرة على أرقام المنصة.', 'حللنا حملات المنصة المكتملة لنجيب عن سؤال واحد: هل الصراحة عن المخاطر تُخيف الداعمين؟' || E'\n\n' || 'النتيجة المعاكسة للحدس: الحملات التي كتبت قسم مخاطر مفصلاً — ثلاث فقرات فأكثر — حققت متوسط تمويل أعلى من الحملات ذات المخاطر المقتضبة، وبفارق ملموس. الداعم يقرأ الصراحة كإشارة جدية، لا كإشارة خطر.' || E'\n\n' || 'الأثر نفسه في التحديثات: حملة تعلن تأخراً بنفسها تحتفظ بداعميها؛ حملة يكتشف داعموها التأخر بأنفسهم تفقدهم. الشفافية ليست فضيلة أخلاقية فحسب — إنها استراتيجية تمويل.', NULL, NULL, 2);
